record.field:
for record in records:
    if not record.x_pre_trip_hse_passed:
        raise UserError("Cannot dispatch tanker: HESMS Pre-Trip Safety & Valve Check must be passed!")
    record['x_state'] = 'in_transit'

for record in records:
    if not record.x_truck_meter_delivered_liters:
        raise UserError("Please enter the Truck Diesel Meter Reading before reconciling.")
    if record.x_leakage_status == 'leakage_alert':
        record['x_state'] = 'investigation'
    else:
        record['x_state'] = 'delivered'
